/**
 * The site's drawings (website spec §2.1): generated by `drawings/gen.py` into
 * `drawings/svg/`, light and dark, one per project, each with its title and
 * the description that is its text alternative (`drawings.json`). The
 * generator copies them to `public/drawings/` (`drawingAssets`).
 */
import DRAWINGS from '../../drawings/svg/drawings.json';

/** The two worked projects; the developer is the default (website spec §2.1). */
export const PROJECTS = ['dev', 'consultant'] as const;
export type Project = (typeof PROJECTS)[number];

export const DRAWING_NAMES = [
  'hero',
  'token-or-mission',
  'repair-scale',
  'modelled-then-verbs',
  'the-map',
  'two-ticks',
  'path-of-a-call',
  'ask-me-first',
  'alone-then-team',
  'agent-terminal',
  'for-plugin-authors',
] as const;
export type DrawingName = (typeof DRAWING_NAMES)[number];

/** Where the generated SVGs are, from the repository root. */
export const DRAWINGS_SOURCE_DIR = 'apps/website/drawings/svg';
/** Where the site serves them, from `public/`. */
export const DRAWINGS_PUBLIC_DIR = 'drawings';

export interface DrawingInfo {
  readonly title: string;
  /** The text alternative: what the drawing shows, in a sentence or three. */
  readonly desc: string;
  readonly w: number;
  readonly h: number;
}

const INFO = DRAWINGS as Readonly<Record<string, DrawingInfo>>;

function key(name: DrawingName, project: Project): string {
  return project === 'dev' ? name : `${name}-consultant`;
}

export function drawingInfo(name: DrawingName, project: Project): DrawingInfo {
  const info = INFO[key(name, project)];
  if (!info) throw new Error(`drawings.json has no '${key(name, project)}': run drawings/gen.py`);
  return info;
}

/** `/drawings/two-ticks-consultant-dark.svg`. */
export function drawingSrc(name: DrawingName, project: Project, theme: 'light' | 'dark'): string {
  return `/${DRAWINGS_PUBLIC_DIR}/${key(name, project)}-${theme}.svg`;
}

/** Every drawing file the site serves: [path from `public/`, source from the repository root]. */
export function drawingAssets(): [string, string][] {
  return DRAWING_NAMES.flatMap((name) =>
    PROJECTS.flatMap((project) =>
      (['light', 'dark'] as const).map((theme): [string, string] => {
        const file = `${key(name, project)}-${theme}.svg`;
        return [`${DRAWINGS_PUBLIC_DIR}/${file}`, `${DRAWINGS_SOURCE_DIR}/${file}`];
      }),
    ),
  );
}

/** A drawing in a page's Markdown twin: its light version, its description as alt text. */
export function drawingMarkdown(name: DrawingName, project: Project): string {
  const info = drawingInfo(name, project);
  return `![${info.desc.replace(/[[\]]/g, '')}](${drawingSrc(name, project, 'light')})`;
}
